def table(headers,rows):
    return '<div class="table"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
style='''<style>*{box-sizing:border-box}body{margin:0;background:#f5f5f3;color:#171717;font:16px/1.65 system-ui}main{max-width:1250px;margin:auto;padding:56px 24px}h1{font-size:clamp(32px,5vw,60px);line-height:1.08;max-width:900px}h2{margin-top:48px}a{color:inherit;text-underline-offset:4px}.status{padding:20px;border-left:5px solid #9b4a08;background:#fff1dc}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.card{background:white;border:1px solid #ccc;padding:22px}strong.metric{font-size:32px;display:block}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #ccc}td{min-width:110px}details{background:white;border:1px solid #ccc;padding:18px;margin-block:12px}summary{font-weight:650;cursor:pointer}code{overflow-wrap:anywhere}li{margin-block:8px}.muted{color:#555}img{max-width:100%;border:1px solid #ccc}</style>'''
body='<p>ULTIMA / CHECKLIST AUDIT · 18 OCTOBER 2026</p><h1>Engineering evidence.<br>Clear launch gates.</h1><div class="status"><strong>Not cleared for Shopify submission.</strong> Code checks pass. Required real-store, measured, public-support and owner evidence is still incomplete. Do not submit a download of the branded QA showroom.</div>'
